package com.yeyamo_mobile.api.partner_service.application;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import com.yeyamo_mobile.api.partner_service.infrastructure.persistence.*;
@Service public class CountryKycRequirementsService {
 private final CountryKycRequirementRepository repository; public CountryKycRequirementsService(CountryKycRequirementRepository r){repository=r;}
 public Requirements requirements(String country,String partnerType,Set<String> received){if(country==null||!country.matches("[A-Za-z]{2}"))throw new PartnerException("COUNTRY_REQUIRED","countryCode ISO-2 is required",HttpStatus.BAD_REQUEST);if(partnerType==null||partnerType.isBlank())throw new PartnerException("PARTNER_TYPE_REQUIRED","partnerType is required",HttpStatus.BAD_REQUEST);var rules=repository.findByCountryCodeAndPartnerTypeAndActiveTrueOrderByDocumentType(country.toUpperCase(Locale.ROOT),partnerType.toUpperCase(Locale.ROOT));Set<String> docs=received==null?Set.of():Set.copyOf(received);var missing=rules.stream().filter(r->r.required&&!docs.contains(r.documentType)).map(r->r.documentType).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));long version=rules.stream().mapToLong(r->r.configurationVersion).max().orElse(0);return new Requirements(country.toUpperCase(Locale.ROOT),partnerType.toUpperCase(Locale.ROOT),version,rules.stream().map(Rule::from).toList(),docs,missing);}
 public record Rule(String documentType,boolean required,Integer validityPeriodDays,String description){static Rule from(CountryKycRequirementEntity e){return new Rule(e.documentType,e.required,e.validityPeriodDays,e.description);}}
 public record Requirements(String countryCode,String partnerType,long configurationVersion,List<Rule> rules,Set<String> receivedDocuments,Set<String> missingDocuments){}
}
